{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (principal is null || resource is null || request is null)
            return new AccessDecision(false, "missing-context", true);

        if (TryGetPreconditionFailure(principal, resource, request, out var failure))
            return failure;

        var authorization = GetAuthorizationFacts(principal, resource, request, delegations);

        if (request.BreakGlass)
            return DecideBreakGlass(authorization.Administrator, request.StrongAuthentication);

        if (TryGetRestrictionFailure(resource, request, out failure))
            return failure;

        return DecideAction(resource, request, authorization);
    }

    private static bool TryGetPreconditionFailure(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (HasInvalidIdentity(principal, resource))
        {
            decision = new AccessDecision(false, "invalid-identity", true);
            return true;
        }

        if (principal.Suspended)
        {
            decision = new AccessDecision(false, "principal-suspended", true);
            return true;
        }

        if (HasTenantMismatch(principal, resource))
        {
            decision = new AccessDecision(false, "tenant-mismatch", true);
            return true;
        }

        if (IsLockedForRequest(resource, request))
        {
            decision = new AccessDecision(false, "resource-locked", true);
            return true;
        }

        if (HasInvalidTime(request))
        {
            decision = new AccessDecision(false, "invalid-time", true);
            return true;
        }

        if (RequiresChallenge(principal, request))
        {
            decision = new AccessDecision(false, "challenge-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool HasInvalidIdentity(Principal principal, Resource resource) =>
        string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id);

    private static bool HasTenantMismatch(Principal principal, Resource resource) =>
        !string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal);

    private static bool IsLockedForRequest(Resource resource, AccessRequest request) =>
        resource.Locked && request.Action != "read";

    private static bool HasInvalidTime(AccessRequest request) =>
        request.MinuteOfDay is < 0 or > 1439;

    private static bool RequiresChallenge(Principal principal, AccessRequest request) =>
        principal.FailedChallenges >= 3 && !request.StrongAuthentication;

    private static AuthorizationFacts GetAuthorizationFacts(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        return new AuthorizationFacts(administrator, operatorRole, auditor, owner, delegated);
    }

    private static AccessDecision DecideBreakGlass(bool administrator, bool strongAuthentication)
    {
        if (!administrator || !strongAuthentication)
            return new AccessDecision(false, "invalid-break-glass", true);

        return new AccessDecision(true, "break-glass", true);
    }

    private static bool TryGetRestrictionFailure(
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "strong-authentication-required", true);
            return true;
        }

        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
        {
            decision = new AccessDecision(false, "trusted-network-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static AccessDecision DecideAction(
        Resource resource,
        AccessRequest request,
        AuthorizationFacts authorization)
    {
        if (request.Action == "delete" && !authorization.Administrator)
            return new AccessDecision(false, "administrator-required", true);

        if (request.Action == "write" && !CanWrite(authorization))
            return new AccessDecision(false, "write-not-authorised", true);

        if (request.Action == "read" && !CanRead(authorization))
            return new AccessDecision(false, "read-not-authorised", false);

        if (request.Action is not ("read" or "write" or "delete"))
            return new AccessDecision(false, "unknown-action", true);

        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        var reason = authorization.Delegated ? "delegated" : "role-or-ownership";
        var auditRequired = outsideBusinessHours || resource.Classification == "restricted";
        return new AccessDecision(true, reason, auditRequired);
    }

    private static bool CanWrite(AuthorizationFacts authorization) =>
        authorization.Administrator ||
        authorization.OperatorRole ||
        authorization.Owner ||
        authorization.Delegated;

    private static bool CanRead(AuthorizationFacts authorization) =>
        authorization.Administrator ||
        authorization.OperatorRole ||
        authorization.Auditor ||
        authorization.Owner ||
        authorization.Delegated;

    private sealed class AuthorizationFacts
    {
        public AuthorizationFacts(
            bool administrator,
            bool operatorRole,
            bool auditor,
            bool owner,
            bool delegated)
        {
            Administrator = administrator;
            OperatorRole = operatorRole;
            Auditor = auditor;
            Owner = owner;
            Delegated = delegated;
        }

        public bool Administrator { get; }
        public bool OperatorRole { get; }
        public bool Auditor { get; }
        public bool Owner { get; }
        public bool Delegated { get; }
    }
